void idle_task_p(void)
{
  /* a yield can enter the idle task with interrupts disabled (wait_release) */
  _ei();
  for (;;)
    ;
}

static void add_task(void (*fn)(void), const struct task_s *t)
{
  ucx_task_add(fn, (char *)t->name, DEFAULT_STACK_SIZE, 0, 0, 0);
  local_task[n_local] = t;
  local_tcb[n_local] = kcb_p->tcb_p;   /* tcb of the task just added */
  released[n_local] = 0;
#ifdef UCX_NOC_TT
  countdown[n_local] = t->offset + 1;
#endif
  n_local++;
}

int32_t app_main(void)
{
  /* idle must be ID = 0 */
  ucx_task_add(idle_task_p, "IDLE", DEFAULT_STACK_SIZE, 0, 0, 0);

  switch (ucx_noc_cpu_id()) {
  case 0: /* (0-0): TPRC */
    add_task(task_TPRC, &TASKS[14]);
    break;
  case 1: /* (1-0): SPES */
    add_task(task_SPES, &TASKS[2]);
    break;
  case 2: /* (2-0): THRC */
    add_task(task_THRC, &TASKS[29]);
    break;
  case 3: /* (3-0): VIBS, TPMS, STAC */
    add_task(task_VIBS, &TASKS[1]);
    add_task(task_TPMS, &TASKS[0]);
    add_task(task_STAC, &TASKS[13]);
    break;
  case 4: /* (0-1): OBDB, USOS, OBMG */
    add_task(task_OBDB, &TASKS[17]);
    add_task(task_USOS, &TASKS[4]);
    add_task(task_OBMG, &TASKS[32]);
    break;
  case 5: /* (1-1): FBU3, VOD1 */
    add_task(task_FBU3, &TASKS[7]);
    add_task(task_VOD1, &TASKS[30]);
    break;
  case 6: /* (2-1): FBU8, VOD2 */
    add_task(task_FBU8, &TASKS[12]);
    add_task(task_VOD2, &TASKS[31]);
    break;
  case 7: /* (3-1): FBU4, BFE4 */
    add_task(task_FBU4, &TASKS[8]);
    add_task(task_BFE4, &TASKS[21]);
    break;
  case 8: /* (0-2): POSI, NAVC, DIRC */
    add_task(task_POSI, &TASKS[3]);
    add_task(task_NAVC, &TASKS[16]);
    add_task(task_DIRC, &TASKS[15]);
    break;
  case 9: /* (1-2): BFE3, FDF1, STPH */
    add_task(task_BFE3, &TASKS[20]);
    add_task(task_FDF1, &TASKS[26]);
    add_task(task_STPH, &TASKS[28]);
    break;
  case 10: /* (2-2): BFE8, FDF2 */
    add_task(task_BFE8, &TASKS[25]);
    add_task(task_FDF2, &TASKS[27]);
    break;
  case 11: /* (3-2): FBU1, BFE1 */
    add_task(task_FBU1, &TASKS[5]);
    add_task(task_BFE1, &TASKS[18]);
    break;
  case 12: /* (0-3): FBU7, BFE7 */
    add_task(task_FBU7, &TASKS[11]);
    add_task(task_BFE7, &TASKS[24]);
    break;
  case 13: /* (1-3): FBU6, BFE6 */
    add_task(task_FBU6, &TASKS[10]);
    add_task(task_BFE6, &TASKS[23]);
    break;
  case 14: /* (2-3): FBU5, BFE5 */
    add_task(task_FBU5, &TASKS[9]);
    add_task(task_BFE5, &TASKS[22]);
    break;
  case 15: /* (3-3): FBU2, BFE2 */
    add_task(task_FBU2, &TASKS[6]);
    add_task(task_BFE2, &TASKS[19]);
    break;
  default:
    break;
  }

  return 1;
}
